import assert from "node:assert/strict";
import base, { type RankedInput } from "./frozen-server/src/simulation/ai_iteration/ranked_adapter";
import { runRankedCase } from "./frozen-server/src/simulation/ai_iteration/ranked_adapter.sniper_donor_guard";
import {
    captureDeterministicRandomState,
    getDeterministicRandomSource,
    setDeterministicRandomSource,
} from "./frozen-server/src/simulation/ai_iteration/sniper_guard_rng";
import type { IterationAdapter, Json } from "./frozen-server/src/simulation/ai_iteration/types";

interface Input {
    ranked: RankedInput;
    protectTeams: number[];
    freeTeams: number[];
}
export const newFields = [
    "leftSetupBudget",
    "rightSetupBudget",
    "leftSetupSpend",
    "rightSetupSpend",
    "observedLiveRandomDraws",
    "deliveryPreviewCalls",
    "catalogCalls",
    "prunedDeliveryPlans",
    "previewRngUuidChecks",
];
const modes = ["current", "protect-entrant", "free-entrant"];
function unused(input: RankedInput, team: number) {
    return !(team === 2 ? input.game.leftDeliveryDraftOverrideUsed : input.game.rightDeliveryDraftOverrideUsed);
}
export function runObserved(input: Input, observe = true) {
    let finalCalls = 0,
        forced = 0,
        mask = 0,
        inStart = false,
        draws = 0,
        previews = 0,
        randomChecks = 0,
        fp: any;
    const catalogs: any[] = [],
        selections: any[] = [];
    const outcome = runRankedCase(input.ranked, (session) => {
        const s = session as any;
        fp = s.fightProperties;
        s.researchSniperProtectionTeams = new Set(input.protectTeams);
        s.researchFreeDeliveryTeams = new Set(input.freeTeams);
        const rng = getDeterministicRandomSource();
        assert.ok(rng);
        setDeterministicRandomSource(() => {
            draws++;
            return rng();
        });
        if (!observe) return;
        s.researchDeliveryCatalogWitness = (event: any) => {
            assert.equal(event.protectSniper, input.protectTeams.includes(event.team));
            assert.equal(event.freeOnly, input.freeTeams.includes(event.team));
            for (const id of event.retained) {
                const plan = event.catalog.find((x: any) => x.id === id);
                assert.ok(plan);
                if (event.protectSniper) assert.ok(plan.sniper >= event.nativeSniper);
                if (event.freeOnly) assert.equal(plan.cost, 0);
            }
            catalogs.push(JSON.parse(JSON.stringify(event)));
        };
        const start = s.tryStartFightIfReady,
            replace = s.rePlaceTeam,
            preview = s.previewDeliverySetup,
            select = s.selectSetupAugmentsForTeam;
        s.tryStartFightIfReady = function (this: any, ...args: any[]) {
            assert.equal(inStart, false);
            inStart = true;
            try {
                return start.apply(this, args);
            } finally {
                inStart = false;
            }
        };
        s.rePlaceTeam = function (this: any, ...args: any[]) {
            if (inStart) {
                finalCalls++;
                forced += Number(args[1] === true);
                mask |= 1 << (args[0] - 1);
            }
            return replace.apply(this, args);
        };
        s.previewDeliverySetup = function (this: any, ...args: any[]) {
            const before = captureDeterministicRandomState(),
                d = draws;
            const score = preview.apply(this, args);
            const after = captureDeterministicRandomState();
            assert.equal(after.source, before.source);
            assert.equal(after.uuidSequence, before.uuidSequence);
            assert.equal(draws, d);
            previews++;
            randomChecks++;
            return score;
        };
        s.selectSetupAugmentsForTeam = function (this: any, ...args: any[]) {
            const selected = select.apply(this, args);
            const event = catalogs.findLast((x) => x.team === args[0]);
            if (event) {
                const sniper = selected.find((x: any) => x.kind === "Sniper")?.value ?? 0;
                if (input.protectTeams.includes(args[0])) assert.ok(sniper >= event.nativeSniper);
                if (args[3] === true)
                    selections.push({
                        team: args[0],
                        nativeSniper: event.nativeSniper,
                        sniper,
                        augments: selected.map((x: any) => ({ ...x })),
                    });
            }
            return selected;
        };
    });
    const spend = (team: number) =>
        fp.getAugmentPlacementLevel(team) +
        fp.getAugmentArmor(team) +
        fp.getAugmentMight(team) +
        fp.getAugmentSniper(team) +
        fp.getAugmentMovement(team) +
        fp.getAugmentEmpower(team);
    return {
        ...outcome,
        diagnostics: {
            ...outcome.diagnostics,
            observedFinalPlacementCalls: finalCalls,
            observedForcedFinalPlacementCalls: forced,
            observedFinalPlacementTeamMask: mask,
            leftSetupBudget: fp.getUpgradePoints(2),
            rightSetupBudget: fp.getUpgradePoints(1),
            leftSetupSpend: spend(2),
            rightSetupSpend: spend(1),
            observedLiveRandomDraws: draws,
            deliveryPreviewCalls: previews,
            catalogCalls: catalogs.length,
            prunedDeliveryPlans: catalogs.reduce((n, x) => n + x.catalog.length - x.retained.length, 0),
            previewRngUuidChecks: randomChecks,
        },
        evidence: { ...(outcome.evidence as Record<string, Json>), sniperDonorObservation: { catalogs, selections } },
    };
}
const adapter: IterationAdapter = {
    async prepare(testCase, arm) {
        const params = arm.parameters as { mode: string };
        assert.deepEqual(Object.keys(params), ["mode"]);
        assert.ok(modes.includes(params.mode));
        const ranked = (await base.prepare(testCase, { id: arm.id, parameters: {} })) as unknown as RankedInput;
        const teams = unused(ranked, ranked.candidateTeam) ? [ranked.candidateTeam] : [];
        return {
            ranked: ranked as unknown as Json,
            protectTeams: params.mode === "protect-entrant" ? teams : [],
            freeTeams: params.mode === "free-entrant" ? teams : [],
        };
    },
    execute(value) {
        const input = value as unknown as Input;
        assert.deepEqual(Object.keys(input).sort(), ["freeTeams", "protectTeams", "ranked"]);
        for (const teams of [input.protectTeams, input.freeTeams]) {
            assert.ok(Array.isArray(teams));
            assert.deepEqual(teams, [...new Set(teams)].sort());
            assert.ok(teams.every((t) => t === input.ranked.candidateTeam && unused(input.ranked, t)));
        }
        assert.ok(!input.protectTeams.length || !input.freeTeams.length);
        const result = runObserved(input);
        assert.equal(result.diagnostics.observedFinalPlacementCalls, 2);
        assert.equal(result.diagnostics.observedForcedFinalPlacementCalls, 2);
        assert.equal(result.diagnostics.observedFinalPlacementTeamMask, 3);
        return result;
    },
};
export default adapter;

