import { expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import adapter, { runObserved, newFields } from "./adapter";
import { validateOutcome } from "./frozen-server/src/simulation/ai_iteration/identity";

const plan = () => JSON.parse(readFileSync(import.meta.dir + "/plan.json", "utf8"));
test("consumed delivery budget makes candidate inputs exactly current", async () => {
    const p = plan();
    let checks = 0;
    for (const c of p.development) {
        const input = (await adapter.prepare(c, p.arms[0])) as any;
        if (
            input.ranked.candidateTeam === 2
                ? input.ranked.game.leftDeliveryDraftOverrideUsed
                : input.ranked.game.rightDeliveryDraftOverrideUsed
        ) {
            for (const arm of p.arms) expect(await adapter.prepare(c, arm)).toEqual(input);
            checks++;
        }
    }
    expect(checks).toBeGreaterThan(0);
});
test("actual native selector skips donor cuts before preview and preserves observer/state controls", async () => {
    const p = plan(),
        c = p.development.find((x: any) => x.id === "known-2-2-delivery-0");
    expect(c).toBeDefined();
    for (const arm of p.arms) {
        const input = (await adapter.prepare(c, arm)) as any;
        const native = runObserved(input, false),
            observed = await adapter.execute(input);
        validateOutcome(native);
        validateOutcome(observed);
        const strip = (v: any) => {
            const d = { ...v.diagnostics };
            for (const k of [
                ...newFields,
                "observedFinalPlacementCalls",
                "observedForcedFinalPlacementCalls",
                "observedFinalPlacementTeamMask",
            ])
                delete d[k];
            const evidence = { ...v.evidence };
            delete evidence.sniperDonorObservation;
            return { ...v, diagnostics: d, evidence };
        };
        expect(strip(observed)).toEqual(strip(native));
        expect(observed.diagnostics.observedLiveRandomDraws).toBe(native.diagnostics.observedLiveRandomDraws);
        expect(observed.diagnostics.previewRngUuidChecks).toBe(observed.diagnostics.deliveryPreviewCalls);
        if (arm.id === "protect-entrant") {
            expect(observed.diagnostics.prunedDeliveryPlans).toBeGreaterThan(0);
            const evidence = observed.evidence as any;
            expect(
                evidence.sniperDonorObservation.selections.some(
                    (x: any) => x.team === input.ranked.candidateTeam && x.nativeSniper === 3 && x.sniper === 3,
                ),
            ).toBe(true);
        }
    }
}, 120000);

