import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
const p = import.meta.dir;
const read = (name: string) => JSON.parse(readFileSync(resolve(p, name), "utf8"));
const seal = read("seal.json");
for (const entry of seal.sources) assert.equal(createHash("sha256").update(readFileSync(resolve(seal.root, entry.path))).digest("hex"), entry.sha256);
const epochs = ["reference", "pooled", "resumed"].map(stage => read(`benchmark/${stage}/development/report.json`).rows.map((r: any) => ({ case: r.caseId, arm: r.arm, outcome: r.execution.outcome })));
assert.deepEqual(epochs[0], epochs[1]); assert.deepEqual(epochs[0], epochs[2]); assert.equal(epochs[0].length, 84);
const expected = read("result.json"), totals: Record<string, number> = {}, families: Record<string, { gain: number; n: number }> = {};
const cases = read("plan.json").development;
let gains = 0, losses = 0;
for (const testCase of cases) {
    const rows = epochs[0].filter((r: any) => r.case === testCase.id), arms = Object.fromEntries(rows.map((r: any) => [r.arm, r.outcome]));
    assert.equal(rows.length, 3);
    for (const [arm, out] of Object.entries(arms) as [string, any][]) { assert.ok(out.terminal); assert.deepEqual(out.qualityErrors, []); totals[arm] = (totals[arm] ?? 0) + 2 * out.score; }
    const delta = 2 * (arms["protect-entrant"].score - arms.current.score); gains += Number(delta > 0); losses += Number(delta < 0);
    const family = families[testCase.family] ??= { gain: 0, n: 0 }; family.gain += delta; family.n++;
}
for (const [arm, total] of Object.entries(totals)) assert.equal(total, 2 * expected.scoreTotals[arm]);
assert.equal(gains, 4); assert.equal(losses, 0); assert.equal(Object.keys(families).length, 14);
const delta = Object.values(families).reduce((n, f) => n + f.gain / (2 * f.n), 0) / 14;
assert.equal(delta, 0.125); assert.equal(expected.guardVsCurrentPoints, delta * 100);
const result = { qualityPassed: true, verifiedSourceFiles: seal.sources.length, coldPersistentCachedRowsExact: 84, physicalGames: 144, integerHalfPointTotals: totals, familyMeanGainPoints: delta * 100, gains, losses, independentFreshFamilies: 0, servingChanged: false };
writeFileSync(resolve(p, "independent-check.json"), JSON.stringify(result, null, 2) + "\n", { flag: "wx" }); console.log(JSON.stringify(result));
